package com.hrcoresystem.hrcore_api.modules.tenant.reports.application.service;

import com.hrcoresystem.hrcore_api.common.exception.BusinessException;
import com.hrcoresystem.hrcore_api.common.security.context.SecurityContextFacade;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantTimezoneService;
import com.hrcoresystem.hrcore_api.modules.tenant.reports.application.dto.ReportFilter;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

@Service public class HrReportService {
 private final JdbcTemplate jdbc; private final TenantTimezoneService timezone; private final SecurityContextFacade security;
 public HrReportService(JdbcTemplate j,TenantTimezoneService t,SecurityContextFacade s){jdbc=j;timezone=t;security=s;}
 public Map<String,Object> employees(ReportFilter f){f=range(f);String w=employeeWhere(f);List<Object>a=employeeArgs(f);Map<String,Object>o=new LinkedHashMap<>();o.put("totalEmployees",count("select count(distinct e.id) from employees e where 1=1"+w,a));for(String s:List.of("ACTIVE","INACTIVE","TERMINATED","ON_LEAVE","SUSPENDED"))o.put(s.toLowerCase(Locale.ROOT)+"Employees",count("select count(distinct e.id) from employees e where e.employment_status=?"+w,prepend(s,a)));o.put("employeesWithoutCurrentAssignment",count("select count(distinct e.id) from employees e where e.employment_status='ACTIVE' and not exists(select 1 from employee_assignments x where x.employee_id=e.id and x.assignment_type='PRIMARY' and x.assignment_status='ACTIVE' and x.start_date<=? and(x.end_date is null or x.end_date>=?))"+w,prependAll(List.of(f.toDate(),f.toDate()),a)));o.put("byDepartment",grouped("select x.department_id id,count(distinct e.id) total from employees e join employee_assignments x on x.employee_id=e.id and x.assignment_type='PRIMARY' and x.assignment_status='ACTIVE' where 1=1"+w+" group by x.department_id",a));o.put("byPosition",grouped("select x.position_id id,count(distinct e.id) total from employees e join employee_assignments x on x.employee_id=e.id and x.assignment_type='PRIMARY' and x.assignment_status='ACTIVE' where 1=1"+w+" group by x.position_id",a));return o;}
 public Map<String,Object> contracts(ReportFilter f){String w="",p="";List<Object>a=new ArrayList<>();if(f.employmentPeriodId()!=null){w+=" and c.employment_period_id=?";a.add(f.employmentPeriodId());}if(f.departmentId()!=null){w+=" and exists(select 1 from employee_assignments x where x.employee_id=c.employee_id and x.department_id=?)";a.add(f.departmentId());}Map<String,Object>o=new LinkedHashMap<>();o.put("totalContracts",count("select count(*) from employment_contracts c where 1=1"+w,a));for(String s:List.of("ACTIVE","DRAFT","PENDING_SIGNATURE","EXPIRED","TERMINATED","CANCELLED"))o.put(s.toLowerCase(Locale.ROOT)+"Contracts",count("select count(*) from employment_contracts c where c.status=?"+w,prepend(s,a)));o.put("byStatus",grouped("select c.status,count(*) total from employment_contracts c where 1=1"+w+" group by c.status",a));return o;}
 public Map<String,Object> attendance(ReportFilter f){f=range(f);String w=" where work_date between ? and ?";List<Object>a=new ArrayList<>(List.of(f.fromDate(),f.toDate()));if(f.employmentPeriodId()!=null){w+=" and employment_period_id=?";a.add(f.employmentPeriodId());}Map<String,Object>o=new LinkedHashMap<>();o.put("fromDate",f.fromDate());o.put("toDate",f.toDate());o.put("totalRecords",count("select count(*) from attendance_records"+w,a));o.put("totalWorkedMinutes",scalar("select coalesce(sum(worked_minutes),0) from attendance_records"+w,a));o.put("totalLateMinutes",scalar("select coalesce(sum(late_minutes),0) from attendance_records"+w,a));o.put("totalEarlyDepartureMinutes",scalar("select coalesce(sum(early_departure_minutes),0) from attendance_records"+w,a));o.put("byStatus",grouped("select status,count(*) total from attendance_records"+w+" group by status",a));o.put("approvedOvertimeMinutes",scalar("select coalesce(sum(o.approved_minutes),0) from attendance_overtime o join attendance_records r on r.id=o.attendance_record_id where r.work_date between ? and ? and o.status='APPROVED'",List.of(f.fromDate(),f.toDate())));return o;}
 public Map<String,Object> leaves(ReportFilter f){f=range(f);String w=" where start_date<=? and end_date>=?";List<Object>a=new ArrayList<>(List.of(f.toDate(),f.fromDate()));if(f.employmentPeriodId()!=null){w+=" and employment_period_id=?";a.add(f.employmentPeriodId());}Map<String,Object>o=new LinkedHashMap<>();o.put("fromDate",f.fromDate());o.put("toDate",f.toDate());o.put("totalRequests",count("select count(distinct id) from leave_requests"+w,a));o.put("approvedDays",scalar("select coalesce(sum(requested_days),0) from leave_requests"+w+" and status='APPROVED'",a));o.put("pendingDays",scalar("select coalesce(sum(requested_days),0) from leave_requests"+w+" and status='PENDING'",a));o.put("byStatus",grouped("select status,count(distinct id) total from leave_requests"+w+" group by status",a));return o;}
 public Map<String,Object> incidents(ReportFilter f){f=range(f);ZoneId z=timezone.requiredZone();List<Object>a=List.of(Timestamp.from(f.fromDate().atStartOfDay(z).toInstant()),Timestamp.from(f.toDate().plusDays(1).atStartOfDay(z).toInstant()));String w=" where occurred_at>=? and occurred_at<?";Map<String,Object>o=new LinkedHashMap<>();o.put("fromDate",f.fromDate());o.put("toDate",f.toDate());o.put("totalIncidents",count("select count(distinct id) from employee_incidents"+w,a));o.put("byStatus",grouped("select status,count(distinct id) total from employee_incidents"+w+" group by status",a));o.put("byType",grouped("select incident_type,count(distinct id) total from employee_incidents"+w+" group by incident_type",a));o.put("bySeverity",grouped("select severity,count(distinct id) total from employee_incidents"+w+" group by severity",a));return o;}
 public byte[] csv(String r,ReportFilter f){Map<String,Object>d=switch(r){case"employees"->employees(f);case"contracts"->contracts(f);case"attendance"->attendance(f);case"leaves"->leaves(f);case"incidents"->incidents(f);default->throw new BusinessException("Reporte no soportado");};StringBuilder b=new StringBuilder("indicador,valor\n");d.forEach((k,v)->b.append(cell(k)).append(',').append(cell(String.valueOf(v))).append('\n'));return b.toString().getBytes(StandardCharsets.UTF_8);}
 public void assertExportAllowed(String r){String p=switch(r){case"employees"->"hr.reports.employees.read";case"contracts"->"hr.reports.contracts.read";case"attendance"->"hr.reports.attendance.read";case"leaves"->"hr.reports.leaves.read";case"incidents"->"hr.reports.incidents.read";default->throw new BusinessException("Reporte no soportado");};if(!security.hasAuthority(p))throw new org.springframework.security.access.AccessDeniedException("No tienes permiso para exportar este reporte");}
 private ReportFilter range(ReportFilter f){LocalDate to=f.toDate()==null?timezone.today():f.toDate(),from=f.fromDate()==null?to.minusDays(30):f.fromDate();if(from.isAfter(to)||from.plusDays(366).isBefore(to))throw new BusinessException("El rango debe ser válido y no superar 366 días");return new ReportFilter(from,to,f.departmentId(),f.employmentPeriodId());}
 private long count(String s,List<?>a){Long v=jdbc.queryForObject(s,Long.class,a.toArray());return v==null?0:v;}private Object scalar(String s,List<?>a){return jdbc.queryForObject(s,Object.class,a.toArray());}private List<Map<String,Object>> grouped(String s,List<?>a){return jdbc.queryForList(s,a.toArray());}private String employeeWhere(ReportFilter f){String w="";if(f.employmentPeriodId()!=null)w+=" and exists(select 1 from employment_periods p where p.id=? and p.employee_id=e.id)";if(f.departmentId()!=null)w+=" and exists(select 1 from employee_assignments x where x.employee_id=e.id and x.department_id=?)";return w;}private List<Object> employeeArgs(ReportFilter f){List<Object>a=new ArrayList<>();if(f.employmentPeriodId()!=null)a.add(f.employmentPeriodId());if(f.departmentId()!=null)a.add(f.departmentId());return a;}private List<Object>prepend(Object x,List<Object>a){List<Object>r=new ArrayList<>();r.add(x);r.addAll(a);return r;}private List<Object>prependAll(List<?>x,List<Object>a){List<Object>r=new ArrayList<>(x);r.addAll(a);return r;}private String cell(String s){if(!s.isEmpty()&&"=+-@".indexOf(s.charAt(0))>=0)s="'"+s;return"\""+s.replace("\"","\"\"")+"\"";}
}
